LIGHT_STYLESHEET = '\n            QMainWindow {\n                background-color: #f4f6f8;\n            }\n\n            QMenuBar {\n                background-color: #ffffff;\n                color: #111827;\n                border-bottom: 1px solid #d8dde3;\n                padding: 3px;\n            }\n\n            QMenuBar::item {\n                background: transparent;\n                color: #111827;\n                padding: 7px 11px;\n            }\n\n            QMenuBar::item:selected,\n            QMenuBar::item:pressed {\n                background-color: #e9eef4;\n                color: #111827;\n                border-radius: 4px;\n            }\n\n            QMenu {\n                background-color: #ffffff;\n                color: #111827;\n                border: 1px solid #d8dde3;\n                padding: 4px;\n            }\n\n            QMenu::item {\n                color: #111827;\n                padding: 7px 30px 7px 12px;\n            }\n\n            QMenu::item:selected {\n                background-color: #e9eef4;\n                color: #111827;\n            }\n\n            QDockWidget {\n                color: #111827;\n                font-weight: 600;\n            }\n\n            QDockWidget::title {\n                background-color: #f3f4f6;\n                color: #111827;\n                padding: 7px;\n                border-bottom: 1px solid #d8dde3;\n            }\n\n            QDockWidget > QWidget {\n                background-color: #ffffff;\n                color: #111827;\n            }\n\n            QLabel {\n                color: #111827;\n            }\n\n            QLabel#pageTitle {\n                font-size: 23px;\n                font-weight: 600;\n            }\n\n            QLabel#recordCountLabel,\n            QLabel#sidebarCountLabel {\n                color: #66717c;\n            }\n\n            QLabel#sidebarTitle {\n                font-size: 14px;\n                font-weight: 600;\n                margin-top: 3px;\n            }\n\n            QLabel#selectionLabel {\n                background-color: #f5f7f9;\n                border: 1px solid #d8dde3;\n                border-radius: 6px;\n                padding: 10px;\n            }\n\n            QGroupBox {\n                background-color: #ffffff;\n                color: #111827;\n                font-weight: 600;\n                border: 1px solid #d8dde3;\n                border-radius: 6px;\n                margin-top: 8px;\n                padding-top: 8px;\n            }\n\n            QGroupBox::title {\n                subcontrol-origin: margin;\n                left: 8px;\n                padding: 0 4px;\n            }\n\n            QCheckBox {\n                background-color: transparent;\n                color: #111827;\n                spacing: 7px;\n                font-weight: 400;\n            }\n\n            /* Unter Windows-Dark-Mode übernimmt der Viewport eines\n               QScrollArea sonst teilweise die dunkle Systempalette. */\n            QScrollArea#categoryScrollArea,\n            QWidget#categoryScrollViewport,\n            QWidget#categoryContainer {\n                background-color: #ffffff;\n                color: #111827;\n                border: none;\n            }\n\n            QLineEdit {\n                min-height: 34px;\n                padding-left: 9px;\n                padding-right: 9px;\n                background-color: #ffffff;\n                color: #111827;\n                border: 1px solid #c9d1d9;\n                border-radius: 5px;\n            }\n\n            QLineEdit:focus {\n                border: 1px solid #2f6fb7;\n            }\n\n\n            QPushButton {\n                min-height: 35px;\n                padding: 0 11px;\n                text-align: left;\n                background-color: #ffffff;\n                color: #111827;\n                border: 1px solid #c9d1d9;\n                border-radius: 5px;\n            }\n\n            QPushButton:hover {\n                background-color: #edf2f6;\n            }\n\n            QPushButton:disabled {\n                color: #9ba4ad;\n                background-color: #f4f6f8;\n            }\n\n            QPushButton#primaryButton {\n                background-color: #2868ad;\n                border-color: #2868ad;\n                color: #ffffff;\n                font-weight: 600;\n            }\n\n            QPushButton#primaryButton:hover {\n                background-color: #215b98;\n            }\n\n            QTableWidget {\n                background-color: #ffffff;\n                alternate-background-color: #f8fafb;\n                color: #111827;\n                border: 1px solid #d8dde3;\n                border-radius: 6px;\n                outline: 0;\n                selection-background-color: #cfe4ff;\n                selection-color: #111827;\n            }\n\n            QTableWidget::item {\n                padding: 7px;\n                border: none;\n                border-bottom: 1px solid #edf0f2;\n            }\n\n            QTableWidget::item:selected {\n                background-color: #cfe4ff;\n                color: #111827;\n                border: none;\n                outline: none;\n            }\n\n            QTableWidget::item:focus {\n                border: none;\n                outline: none;\n            }\n\n            /* Auch der leere Bereich rechts neben der letzten\n               Tabellenüberschrift erhält eine helle Farbe. */\n            QHeaderView {\n                background-color: #edf1f5;\n                color: #111827;\n            }\n\n            QHeaderView::section {\n                background-color: #edf1f5;\n                color: #111827;\n                border: none;\n                border-right: 1px solid #d8dde3;\n                border-bottom: 1px solid #d8dde3;\n                padding: 8px;\n                font-weight: 600;\n            }\n\n            QTableCornerButton::section {\n                background-color: #edf1f5;\n                border: none;\n                border-right: 1px solid #d8dde3;\n                border-bottom: 1px solid #d8dde3;\n            }\n\n            /* Explizite Scrollbar-Farben verhindern unleserliche\n               Steuerelemente bei aktivem Windows-Dark-Mode. */\n            QScrollBar:horizontal {\n                background-color: #e5e7eb;\n                height: 16px;\n                margin: 0;\n                border: 1px solid #cbd5e1;\n            }\n\n            QScrollBar::handle:horizontal {\n                background-color: #8b96a3;\n                min-width: 36px;\n                margin: 2px;\n                border-radius: 5px;\n            }\n\n            QScrollBar::handle:horizontal:hover {\n                background-color: #647181;\n            }\n\n            QScrollBar:vertical {\n                background-color: #e5e7eb;\n                width: 16px;\n                margin: 0;\n                border: 1px solid #cbd5e1;\n            }\n\n            QScrollBar::handle:vertical {\n                background-color: #8b96a3;\n                min-height: 36px;\n                margin: 2px;\n                border-radius: 5px;\n            }\n\n            QScrollBar::handle:vertical:hover {\n                background-color: #647181;\n            }\n\n            QScrollBar::add-line,\n            QScrollBar::sub-line {\n                width: 0;\n                height: 0;\n                background: none;\n                border: none;\n            }\n\n            QScrollBar::add-page,\n            QScrollBar::sub-page {\n                background: transparent;\n            }\n\n            QToolTip {\n                background-color: #ffffff;\n                color: #111827;\n                border: 1px solid #9ca3af;\n                padding: 4px;\n            }\n\n            QStatusBar {\n                background-color: #ffffff;\n                color: #5c6670;\n                border-top: 1px solid #d8dde3;\n            }\n\n            QLabel#userStatusLabel {\n                padding-left: 12px;\n                padding-right: 8px;\n                color: #5c6670;\n            }\n            '


def apply_light_theme(widget: QWidget) -> None:
    """Wendet ein Windows-Dark-Mode-unabhängiges helles Design an."""
    widget.setStyleSheet(LIGHT_STYLESHEET)